tool_input.new_string:
ok(el('alertBox').innerHTML.indexOf('缺 dps') >= 0, 'missDps: config 真缺 dps 时一定报（不受 margin 影响）');

// 【分级设计】只配 yld 不配 dps：红条报「缺 dps」，但 yld 反推仍能算目标买价 → 推荐区照常出（不阻断）
// 这个用例锁死「红条 ≠ 阻断」的向后兼容设计，防止将来被“顺手改成一致”而破坏现有 config
P._clearMargin();
P.applyConfig({ targets: [{ code: '601000', name: '唐山港', ind: '交运', mkt: '沪', w: 60, governance: 'state', ocfd2y: 2, payout2y: 50, yld: 6, vol: 10 }], rules: sandbox.PANEL_CONFIG.rules, margin: sandbox.PANEL_CONFIG.margin });
ok(sandbox.dpsOf({ yld: 6 }, 10) === 0.6, '分级设计: dpsOf 能用 yld 反推 dps（10×6%=0.6）');
ok(!(sandbox.PANEL_CONFIG.targets[0].dps != null), '分级设计: 前置条件——该 target 确实没配 dps');
P.render();
ok(el('alertBox').innerHTML.indexOf('缺 dps') >= 0, '分级设计: 未显式配置 dps → 红条提示「缺 dps」');
// margin 未就绪时不算推荐；注入反推出的 margin 后应能正常进推荐（不因缺 dps 被跳过）
P._setMargin('601000.SH', { code: '601000', name: '唐山港', price: 10, dps: 0.6, targetYld: 5, targetYldConst: 'x', curYld: 6, yldAvg: 5, yldPct: 50, histYldN: 700, targetBuyAbsolute: 12, targetBuyConservative: 11, boll: [] });
const rD = P.rowsNow();
ok(rD[0].dpsMissing === false, '分级设计: yld 反推出 dps 后 dpsMissing=false（不跳过）');
const planD = P.buildPlan(100000, rD, P.totals(rD));
ok(!planD.skipped.some(x => /dps 未配置/.test(x.why)), '分级设计: 红条报缺 dps，但推荐区不因它跳过（红条≠阻断）');

